(function(E){ const x = E["hr-m7"] = E["hr-m7"] || {units:{}}; x.units["hr-7-2"] = {"explain":{"id":"c-hr-7-2-e","course":"hr","unit":"hr-7-2","type":"explain","level":"B1","title":{"en":"Records and privacy","tr":"Kayıtlar ve gizlilik","fa":"سوابق و حریم خصوصی"},"objective":{"en":"After this lesson, you can answer a request for personal data and keep records fair and factual.","tr":"Bu dersin sonunda kişisel veri talebine cevap verebilecek, kayıtları adil ve olgulara dayalı tutabileceksin.","fa":"بعد از این درس می‌توانی به درخواست اطلاعات شخصی جواب بدهی و سوابق را منصفانه و بر پایه‌ی واقعیت نگه داری."},"hook":{"en":"Answer a data request calmly, with a date. In the UK and the EU, a candidate can ask to read your notes. Karim asks to see his interview notes. One of them is not a note Leyla wrote.","tr":"Veri talebine sakince ve tarih vererek cevap ver. Birleşik Krallık ve AB’de aday notlarını okumak isteyebilir. Karim mülakat notlarını görmek istiyor. Notlardan biri Leyla’nın yazdığı bir not değil.","fa":"به درخواست اطلاعات آرام و با تاریخ جواب بده. در بریتانیا و اتحادیه‌ی اروپا متقاضی می‌تواند بخواهد یادداشت‌هایت را بخواند. کریم می‌خواهد یادداشت‌های مصاحبه‌اش را ببیند. یکی از یادداشت‌ها را لیلا ننوشته."},"before":{"en":"Reply calmly to a request for data: thank the person, say what you will send and give a date.","tr":"Bir veri talebine sakin bir cevap yaz: Kişiye teşekkür et, ne göndereceğini söyle ve bir tarih ver.","fa":"به یک درخواست داده آرام جواب بده: از آن شخص تشکر کن، بگو چه چیزی می‌فرستی و یک تاریخ بده."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Answer calmly, with a date","tr":"Sakince cevap ver, tarih de söyle","fa":"آرام جواب بده و تاریخ هم بگو"},"body":{"en":"A request for data is a normal task, not an attack. So thank the person, say what you will send and give a date. Keep every note fair from the start.","tr":"Veri talebi bir saldırı değil, olağan bir iştir. Bu yüzden kişiye teşekkür et, ne göndereceğini söyle ve bir tarih ver. Her notu baştan adil tut.","fa":"درخواست اطلاعات یک کار عادی است، نه حمله. پس از آن شخص تشکر کن، بگو چه چیزی می‌فرستی و تاریخ بده. هر یادداشت را از اول منصفانه بنویس."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Reporting a request: asked whether, said that","tr":"Bir talebi aktarmak: asked whether, said that","fa":"نقل یک درخواست: asked whether، said that"},"steps":[{"en":"A yes/no question becomes asked whether/if + statement.","tr":"Evet/hayır sorusu asked whether/if + düz cümleye dönüşür.","fa":"سؤال بله/نه به asked whether/if و یک جمله‌ی خبری تبدیل می‌شود.","ex":"He asked whether he could see the notes."},{"en":"A wh- question keeps its word but uses statement order.","tr":"Soru kelimeli soru kelimesini korur ama düz cümle sırası kullanır.","fa":"سؤال با کلمه‌ی پرسشی، همان کلمه را نگه می‌دارد اما ترتیب جمله‌ی خبری می‌گیرد.","ex":"He asked when he would get them."},{"en":"Say + that; tell + a person + that.","tr":"Say + that; tell + kişi + that.","fa":"بعد از say کلمه‌ی that می‌آید؛ بعد از tell اول شخص و بعد that.","ex":"I told him that we would reply by 20 May."}],"table":{"headers":{"en":["He said","You report"],"tr":["Söylediği","Aktarman"],"fa":["گفت","نقل تو"]},"rows":[["\"Can I see my notes?\"","He asked whether he could see his notes."],["\"When will I get them?\"","He asked when he would get them."],["\"I need them for my next interview.\"","He said that he needed them for his next interview."]]},"tip":{"en":"Do not keep the question order after asked: asked whether he could, not asked could he.","tr":"Asked’den sonra soru sırasını koruma: asked could he değil, asked whether he could.","fa":"بعد از asked ترتیب سؤالی را نگه ندار: asked whether he could، نه asked could he."},"wrong":"He asked could he see his notes.","right":"He asked whether he could see his notes."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"Thank you for your request of...","meaning":{"en":"Confirms the request and its date.","tr":"Talebi ve tarihini teyit eder.","fa":"درخواست و تاریخش را تأیید می‌کند."}},{"phrase":"Please find attached...","meaning":{"en":"Says what you are sending.","tr":"Ne gönderdiğini söyler.","fa":"می‌گوید چه چیزی پیوست کرده‌ای."}},{"phrase":"personal data","meaning":{"en":"Any information about a person who can be identified.","tr":"Kimliği belirlenebilen bir kişiyle ilgili her bilgi.","fa":"هر اطلاعاتی درباره‌ی فردی که بشود او را شناسایی کرد."}},{"phrase":"Write every note as if the person will read it.","meaning":{"en":"The rule for fair records.","tr":"Adil kayıtların kuralı.","fa":"قاعده‌ی سوابق منصفانه."}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Notes are personal data","tr":"Notlar kişisel veridir","fa":"یادداشت‌ها اطلاعات شخصی‌اند"},"body":{"en":"In the UK and the EU, a candidate can ask for their interview notes, and the employer usually has one month to answer. Other countries have their own data laws. Never delete a note after someone asks for it; write fair notes from the start.","tr":"Birleşik Krallık’ta ve AB’de bir aday mülakat notlarını isteyebilir; işverenin cevap vermek için genellikle bir ayı vardır. Başka ülkelerin de kendi veri yasaları vardır. Biri bir notu istedikten sonra onu asla silme; notları en baştan adil yaz.","fa":"در بریتانیا و اتحادیه‌ی اروپا متقاضی می‌تواند یادداشت‌های مصاحبه‌اش را بخواهد و کارفرما معمولاً یک ماه برای جواب دادن وقت دارد. کشورهای دیگر هم قانون‌های خودشان را درباره‌ی اطلاعات شخصی دارند. وقتی کسی یادداشتی را خواست، هیچ‌وقت آن را پاک نکن؛ از اول یادداشت منصفانه بنویس."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از جواب دفاعی تا جواب آرام با تاریخ"},"text":"Facts: The person asked for their notes. You can send a copy by 20 June.","item":"Why do you need these? They are internal documents.","why":{"en":"Weak: defensive, with no date. Strong: thanks, what, when.","tr":"Zayıf: savunmacı, tarih yok. Güçlü: teşekkür, ne, ne zaman.","fa":"نسخه‌ی اول حالت دفاعی دارد و تاریخ ندارد. نسخه‌ی دوم تشکر می‌کند و می‌گوید چه چیزی را کی می‌فرستد."},"answer":"Thank you for your request. We will send you a copy of your notes by 20 June.","cut":["Why do you need these?","They are internal documents."],"cutHint":{"en":"Tap what treats a normal request like an attack.","tr":"Olağan bir talebe saldırıymış gibi davranan sözlere dokun.","fa":"روی حرف‌هایی بزن که با یک درخواست عادی مثل حمله برخورد می‌کنند."}},"quick":{"prompt":"A candidate emails to ask for her interview notes. What is the best first reply?","options":["Thank her, say what you will send and give a date","Ask why she wants them","Tell her the notes are internal"],"correct":0,"why":{"en":"Thank her, say what you will send and give a date: a request for data is a normal task, not an attack.","tr":"Teşekkür et, ne göndereceğini söyle ve bir tarih ver: Veri talebi bir saldırı değil, olağan bir iştir.","fa":"تشکر کن، بگو چه چیزی می‌فرستی و یک تاریخ بده: درخواست داده یک کار عادی است، نه حمله."},"point":1},"remember":{"en":"Reported questions: whether or a wh- word, then statement order. Result of this lesson: you can answer a data request calmly. You also have the written reply.","tr":"Aktarılan sorular: whether ya da soru kelimesi, sonra düz cümle sırası. Bu dersin sonucu: bir veri talebine sakince cevap verebilirsin ve elinde yazılı cevabın olur.","fa":"در سؤال‌های نقل‌شده، whether یا کلمه‌ی پرسشی می‌آید و بعد ترتیب جمله‌ی خبری. حالا می‌توانی به درخواست اطلاعات آرام جواب بدهی. جواب نوشته‌شده هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Neutral records: It was noted that...","tr":"Tarafsız kayıtlar: It was noted that...","fa":"سوابق بی‌طرف: It was noted that..."},"steps":[{"en":"Record a fact without a name: It was noted that + clause.","tr":"Bir olguyu isim vermeden kaydet: It was noted that + cümle.","fa":"یک واقعیت را بدون اسم ثبت کن: It was noted that و یک جمله.","ex":"It was noted that the candidate arrived early."},{"en":"Report a statement: It was agreed / confirmed that...","tr":"Bir ifadeyi aktar: It was agreed / confirmed that...","fa":"یک حرف را نقل کن: It was agreed / confirmed that...","ex":"It was confirmed that the notes would be sent by 20 May."},{"en":"Keep opinions out: report what happened, not what you think.","tr":"Görüşleri dışarıda bırak: ne düşündüğünü değil, ne olduğunu aktar.","fa":"نظرها را کنار بگذار: آنچه اتفاق افتاد را بنویس، نه برداشتت را.","ex":"It was noted that two questions were not answered."}],"body":{"en":"B2 track: in your reply, use one It was ... that sentence.","tr":"B2 yolu: cevabında It was ... that ile bir cümle kullan.","fa":"مسیر B2: در جوابت یک جمله با It was ... that بیاور."}},"source":{"en":"Based on ICO guidance on subject access requests and the GDPR.","tr":"ICO’nun kişisel verilere erişim talepleri rehberine ve GDPR’a dayanır.","fa":"بر پایه‌ی راهنمای ICO درباره‌ی درخواست دسترسی به اطلاعات شخصی و GDPR."}},"story":{"id":"c-hr-7-2-s","course":"hr","unit":"hr-7-2","level":"B1","genre":"Workplace","title":{"en":"The Notes","tr":"Notlar","fa":"یادداشت‌ها"},"text":"Three months after his rejection, Karim sent Leyla a short email. \"Could I please have a copy of my interview notes? I want to understand what I can do better.\"\n\nLeyla opened his file. Her own notes were fine: what Karim said, what he did on the forklift test, the questions he answered well and the two he did not. Then she found a yellow sticky note in Omar's handwriting. A bit lazy maybe.\n\nShe went to Omar's desk. \"Karim asked whether he could see his notes. Your sticky note is in the file.\"\n\nOmar shrugged. \"Throw it away. Problem solved.\"\n\n\"I can't,\" Leyla said. \"Once someone asks for their data, we can't delete it. And it is his data. He has a right to see what we wrote about him, and our policy says we reply within one month.\"\n\nOmar looked at the yellow square for a long time. \"I wrote that in ten seconds.\"\n\n\"I know. That's why next time we write every note as if the candidate will read it.\"\n\nLeyla replied to Karim the same afternoon. She thanked him for his request, told him that the notes would be sent by 20 May, and added one line Omar agreed to: \"One comment in the file is not based on evidence, and we have apologised for it.\"","vocab":[{"word":"sticky note","en":"A small piece of paper that sticks to things.","tr":"yapışkanlı not kâğıdı","fa":"کاغذ یادداشت چسب‌دار"},{"word":"shrug","en":"To lift your shoulders to show you do not care.","tr":"omuz silkmek","fa":"شانه بالا انداختن"},{"word":"evidence","en":"Facts that show something is true.","tr":"kanıt","fa":"شاهد؛ مدرک"},{"word":"policy","en":"A company's written rule.","tr":"şirket kuralı, politika","fa":"آیین‌نامه؛ سیاست شرکت"}],"quiz":[{"prompt":"Why can't Leyla throw the sticky note away?","options":["Karim has already asked for his data","Omar wants to keep it","It has the date on it"],"correct":0},{"prompt":"Which sentence reports Karim's question correctly?","options":["Karim asked could he see his notes.","Karim asked whether he could see his notes.","Karim asked that he could see his notes."],"correct":1},{"prompt":"What is the rule for notes from now on?","options":["Write them as if the candidate will read them","Write them only on paper","Keep them shorter"],"correct":0},{"prompt":"How might Karim feel when he reads the reply?","options":["Respected, because Atlas was honest about the comment","Confused about what he asked for","Angry that he waited one month"],"correct":0}],"notice":{"en":"Notice how Leyla reports Karim's question to Omar.","tr":"Leyla’nın Karim’in sorusunu Omar’a nasıl aktardığına dikkat et.","fa":"دقت کن لیلا سؤال کریم را چطور برای عمر نقل می‌کند."},"bridge":{"en":"Next: explain the notes rule to a manager.","tr":"Sırada: not kuralını bir yöneticiye açıkla.","fa":"قدم بعد: قاعده‌ی یادداشت‌نویسی را برای یک مدیر توضیح بده."}},"speaking":{"id":"hr-7-2","course":"hr","unit":"hr-7-2","rounds":[90,60],"topic":{"en":"Explaining a Records Rule to a Manager","tr":"Bir Yöneticiye Kayıt Kuralını Açıklamak","fa":"توضیح قاعده‌ی سوابق برای یک مدیر"},"warmup":{"en":"Have you ever written something about a person at work that you would not want them to read?","tr":"İş yerinde biri hakkında, onun okumasını istemeyeceğin bir şey yazdın mı hiç?","fa":"تا حالا در محیط کار درباره‌ی کسی چیزی نوشته‌ای که نخواهی خودش بخواند؟"},"questions":[{"en":"Report the candidate's request to the manager.","tr":"Adayın talebini yöneticiye aktar.","fa":"درخواست متقاضی را برای مدیر نقل کن."},{"en":"Explain why the note cannot be deleted now.","tr":"Notun neden artık silinemeyeceğini açıkla.","fa":"توضیح بده چرا الان نمی‌شود یادداشت را پاک کرد."},{"en":"Say how long you have to reply.","tr":"Cevap vermek için ne kadar süreniz olduğunu söyle.","fa":"بگو چقدر برای جواب دادن وقت هست."},{"en":"Suggest the rule for future notes.","tr":"Gelecekteki notlar için kuralı öner.","fa":"قاعده‌ی یادداشت‌های بعدی را پیشنهاد بده."}],"followups":[{"en":"Say it in 90 seconds, then in 60, without blaming the manager.","tr":"Yöneticiyi suçlamadan önce 90, sonra 60 saniyede söyle.","fa":"بدون سرزنش مدیر، یک بار در ۹۰ ثانیه و بعد در ۶۰ ثانیه بگو."},{"en":"Now say what data your company keeps about staff, and who can see it.","tr":"Şimdi şirketinin çalışanlar hakkında hangi verileri tuttuğunu ve kimlerin görebildiğini söyle.","fa":"حالا بگو شرکتت چه اطلاعاتی از کارمندان نگه می‌دارد و چه کسی می‌تواند آن‌ها را ببیند."}],"expressions":[{"phrase":"He asked whether...","meaning":{"en":"Reports a yes/no question.","tr":"Evet/hayır sorusunu aktarır.","fa":"سؤال بله/نه را نقل می‌کند."}},{"phrase":"Once someone asks for their data, we can't delete it.","meaning":{"en":"States the rule.","tr":"Kuralı söyler.","fa":"قاعده را می‌گوید."}},{"phrase":"Next time, let's write it as if they will read it.","meaning":{"en":"Suggests a better habit.","tr":"Daha iyi bir alışkanlık önerir.","fa":"عادت بهتری را پیشنهاد می‌کند."}}],"culture":{"en":"Talk about the note, not the person who wrote it. A calm \"next time\" works better than blame, and it protects the company too.","tr":"Notu yazan kişiden değil, nottan bahset. Sakin bir \"bir dahaki sefere\" suçlamadan daha iyi işler ve şirketi de korur.","fa":"درباره‌ی یادداشت حرف بزن، نه درباره‌ی کسی که نوشته. یک «دفعه‌ی بعد» آرام از سرزنش بهتر جواب می‌دهد و از شرکت هم محافظت می‌کند."},"model":"Omar, Karim asked whether he could see his interview notes. Your sticky note is in his file, and once someone asks for their data, we can't delete it. We have one month to reply, so I'd like to send everything by 20 May. I suggest we add a short apology for that comment. Next time, let's write every note as if the candidate will read it.","selfCheck":[{"en":"I reported the request with asked whether.","tr":"Talebi asked whether ile aktardım.","fa":"درخواست را با asked whether نقل کردم."},{"en":"I explained why we cannot delete the note.","tr":"Notu neden silemeyeceğimizi açıkladım.","fa":"توضیح دادم چرا نمی‌توانیم یادداشت را پاک کنیم."},{"en":"I gave the time limit.","tr":"Süre sınırını söyledim.","fa":"مهلت را گفتم."},{"en":"I suggested a rule without blame.","tr":"Suçlamadan bir kural önerdim.","fa":"بدون سرزنش یک قاعده پیشنهاد دادم."}]},"writing":{"id":"c-hr-7-2-w","course":"hr","unit":"hr-7-2","type":"writing","title":{"en":"Your reply to Karim","tr":"Karim’e cevabın","fa":"جواب تو به کریم"},"difficulty":"medium","prompt":{"en":"Reply to Karim (50-80 words): thank him for his request, say what you will send and by when, and report one thing he asked.","tr":"Karim’e cevap yaz (50-80 kelime): talebi için teşekkür et, ne göndereceğini ve ne zamana kadar göndereceğini söyle ve sorduğu bir şeyi aktar.","fa":"به کریم جواب بده (۵۰ تا ۸۰ کلمه): برای درخواستش تشکر کن، بگو چه چیزی و تا کی می‌فرستی و یکی از چیزهایی را که پرسیده نقل کن."},"model":"Dear Karim, thank you for your request of 20 April for your interview notes. You asked whether the notes included your forklift test, and they do. We will send you a copy of all the notes by 20 May. One comment in the file is not based on evidence, and we apologise for it. Please contact me if you have any questions. Kind regards, Leyla Karimi","frame":"Dear ___, thank you for your request of ___ for ___. You asked whether ___, and ___. We will send you ___ by ___. Please contact me if ___. Kind regards, ___","words":[{"word":"request"},{"word":"asked whether"},{"word":"by"}],"minWords":50,"minSentences":5,"rubric":["Task done: thanks, what you will send, the date, one reported question","Organised: thanks, answer, date, contact","Language: reported question with whether; by + date","Tone: honest, polite and calm"],"rubricI18n":{"tr":["Görev: teşekkür, gönderilecekler, tarih, aktarılan bir soru","Düzen: teşekkür, cevap, tarih, iletişim","Dil: whether ile aktarılan soru; by + tarih","Üslup: dürüst, kibar ve sakin"],"fa":["کامل بودن کار: تشکر، چیزی که می‌فرستی، تاریخ، یک سؤال نقل‌شده","نظم: تشکر، جواب، تاریخ، راه تماس","زبان: سؤال نقل‌شده با whether؛ by با تاریخ","لحن: صادق، مؤدب و آرام"]},"portfolio":null,"parts":[{"t":{"en":"Thanks for the request","tr":"Talep için teşekkür","fa":"تشکر برای درخواست"},"find":["thank you for your request","request"],"sample":"his request of 20 April"},{"t":{"en":"The question he asked","tr":"Sorduğu soru","fa":"سؤالی که پرسید"},"find":["you asked whether","asked whether"],"sample":"whether the notes include his forklift test"},{"t":{"en":"What you will send, and when","tr":"Ne göndereceğin ve ne zaman","fa":"چه چیزی می‌فرستی و کی"},"find":["we will send","by 20 may"],"sample":"a copy of all the notes by 20 May"},{"t":{"en":"Who to contact","tr":"Kime ulaşılacağı","fa":"با چه کسی تماس بگیرد"},"find":["contact me","questions"],"sample":"contact me with any questions"}]},"perspective":{"id":"c-hr-7-2-p","course":"hr","unit":"hr-7-2","type":"perspective","title":{"en":"Through Karim's eyes","tr":"Karim’in gözünden","fa":"از نگاه کریم"},"minSentences":2,"prompt":{"en":"You are Karim. You have just read your interview notes, including the apology. Write 2 sentences in first person: what will you do with them, and what do you think of Atlas now?","tr":"Sen Karim’sin. Özür de dahil mülakat notlarını az önce okudun. Birinci tekil şahısla 2 cümle yaz: bu notlarla ne yapacaksın ve şimdi Atlas hakkında ne düşünüyorsun?","fa":"تو کریم هستی و همین حالا یادداشت‌های مصاحبه‌ات را، همراه با عذرخواهی، خوانده‌ای. از زبان خودت دو جمله بنویس: با این یادداشت‌ها چه می‌کنی و حالا درباره‌ی اطلس چه فکر می‌کنی؟"}},"exit":{"id":"c-hr-7-2-x","course":"hr","unit":"hr-7-2","type":"exit","items":[{"from":"hr-7-2","kind":"blank","point":2,"prompt":"He asked ___ he could have a copy of the notes.","options":["whether","that","what"],"correct":0,"why":{"en":"whether: a reported yes/no question uses whether (or if). 'That' reports a statement, and 'what' needs a missing thing.","tr":"whether: aktarılan evet/hayır sorusu whether (ya da if) kullanır. 'That' bir bildirimi aktarır; 'what' eksik bir şey ister.","fa":"whether درست است، چون برای نقل سؤال بله‌یا‌نه whether یا if می‌آید. that جمله‌ی خبری را نقل می‌کند و what دنبال چیزی است که جمله ندارد."},"hint2":{"en":"The original was a yes/no question (Can I have a copy?). Which word reports a yes/no question?","tr":"Asıl soru bir evet/hayır sorusuydu (Can I have a copy?). Evet/hayır sorusu hangi kelimeyle aktarılır?","fa":"سؤال اصلی بله/نه بود (⁨Can I have a copy?).⁩ سؤال بله/نه با کدام کلمه نقل می‌شود؟"}},{"from":"hr-7-2","kind":"blank","point":2,"prompt":"She asked when ___ the documents.","options":["she would get","would she get","did she get"],"correct":0,"why":{"en":"she would get: a reported question keeps statement order. 'Would she get' and 'did she get' are question order.","tr":"she would get: aktarılan soru düz sırayı korur. 'Would she get' ve 'did she get' soru sırasıdır.","fa":"she would get درست است، چون سؤال نقل‌شده ترتیب خبری دارد. would she get و did she get ترتیب سؤالی‌اند."},"hint2":{"en":"In a reported question the order is the order of a statement: subject, then verb. Which option has that order?","tr":"Aktarılan bir soruda sıra düz cümle sırasıdır: önce özne, sonra fiil. Hangi seçenekte bu sıra var?","fa":"در سؤالِ نقل‌شده، ترتیب مثل جمله‌ی خبری است: اول فاعل، بعد فعل. کدام گزینه این ترتیب را دارد؟"}},{"from":"hr-7-2","kind":"mcq","point":4,"prompt":"A candidate has asked for her notes. A manager wants to delete one rude comment first. What do you say?","options":["We can't delete it now; she has asked for her data.","Fine, delete it quickly.","Rewrite it in nicer words before you send it."],"correct":0,"why":{"en":"We can't delete it now: she has asked for her data, and notes about her are personal data. Deleting or rewriting the comment would hide it from her.","tr":"Şimdi silemeyiz: verilerini istedi ve onunla ilgili notlar kişisel veridir. Yorumu silmek ya da yeniden yazmak onu ondan saklamak olur.","fa":"الان نمی‌توانیم پاکش کنیم، چون داده‌هایش را خواسته و یادداشت‌های مربوط به او داده‌ی شخصی است. پاک کردن یا بازنویسی آن یعنی پنهان کردنش از او."}},{"from":"hr-7-1","kind":"blank","prompt":"Your references ___ before your first day.","options":["are checked","check","are check"],"correct":0,"point":2,"why":{"en":"are checked: the references receive the action, so are + past participle. 'Check' says the references check something, and 'are check' drops -ed.","tr":"are checked: referanslar eylemi alır, bu yüzden are + üçüncü hâl. 'Check' referansların bir şeyi kontrol ettiğini söyler; 'are check' -ed'i düşürür.","fa":"⁨are checked⁩ درست است، چون معرف‌ها بررسی می‌شوند و ⁨are⁩ و اسم مفعول لازم است. ⁨check⁩ یعنی خود معرف‌ها چیزی را بررسی می‌کنند و ⁨are check⁩ ⁨-ed⁩ ندارد."}},{"from":"hr-6-3","kind":"blank","prompt":"Absence ___ to 2% in March.","options":["fell","felt","fallen"],"correct":0,"point":2,"why":{"en":"fell: the past of 'fall' is fell. 'Felt' is the past of feel, and 'fallen' needs has or had.","tr":"fell: 'fall' fiilinin geçmişi fell'dir. 'Felt' feel'in geçmişidir; 'fallen' has ya da had ister.","fa":"fell درست است، چون گذشته‌ی fall همان fell است. felt گذشته‌ی feel است و fallen به has یا had نیاز دارد."}},{"from":"hr-4-1","kind":"blank","prompt":"Part-time staff are ___ to sick pay.","options":["entitled","allowed","given"],"correct":0,"point":2,"why":{"en":"entitled: 'entitled to' means it is their right. 'Allowed' is permission, and 'given to' doesn't make this meaning.","tr":"entitled: 'entitled to' bunun onların hakkı olduğu demektir. 'Allowed' izindir; 'given to' bu anlamı vermez.","fa":"entitled درست است، چون entitled to یعنی حق آن‌هاست. allowed یعنی اجازه و given to این معنی را نمی‌دهد."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
